import os
import subprocess
import glob
import re
from datetime import datetime
def load_environment_variables(env_file):
    try:
        with open(env_file, 'r') as f:
            for line in f:
                if line.startswith('export '):
                    line = line[7:].strip()
                    if '=' in line:
                        key, value = line.split('=', 1)
                        value = value.strip().strip('"').strip("'")
                        os.environ[key] = value
        return True
    except Exception as e:
        return False
def find_latest_log_file(log_dir):
    log_patterns = ["gaussdb-*.log", "postgres*.log"]
    latest_file = None
    latest_time = 0
    for pattern in log_patterns:
        files = glob.glob(os.path.join(log_dir, pattern))
        for file in files:
            if os.path.isfile(file):
                file_time = os.path.getmtime(file)
                if file_time > latest_time:
                    latest_time = file_time
                    latest_file = file
    return latest_file
def check_keyword_in_log(log_file, keyword):
    try:
        with open(log_file, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if keyword in line:
                    return True
        return False
    except Exception as e:
        return False
def find_dn_cn_directories(base_dir):
    directories = []
    dn_dirs = glob.glob(os.path.join(base_dir, "dn_*"))
    directories.extend([d for d in dn_dirs if os.path.isdir(d)])
    cn_dirs = glob.glob(os.path.join(base_dir, "cn_*"))
    directories.extend([d for d in cn_dirs if os.path.isdir(d)])
    return directories
def main():
    env_file = "/home/Ruby/gauss_env_file"
    if not load_environment_variables(env_file):
        print("true",end="")
        return
    gausslog_path = os.environ.get('GAUSSLOG')
    if not gausslog_path:
        print("true",end="")
        return
    log_base_dir = os.path.join(gausslog_path, "gs_log")
    target_dirs = find_dn_cn_directories(log_base_dir)
    if not target_dirs:
        print("true",end="")
        return
    keyword = "WAIT barrier flush or updated to media"
    found_keyword = False
    for directory in target_dirs:
        latest_log = find_latest_log_file(directory)
        if latest_log and check_keyword_in_log(latest_log, keyword):
            found_keyword = True
            break
    if found_keyword:
        print("false")
    else:
        print("true",end="")
if __name__ == "__main__":
    main()
